import{_ as e,o as t,c as s,a5 as n}from"./chunks/framework.BEZBAInb.js";const m=JSON.parse('{"title":"异步运镜","description":"","frontmatter":{"title":"异步运镜","order":4},"headers":[],"relativePath":"zh/latest/tutorial/script/camera/asyncam.md","filePath":"zh/latest/tutorial/script/camera/asyncam.md","lastUpdated":1788455378000}'),d={name:"zh/latest/tutorial/script/camera/asyncam.md"};function l(o,a,c,i,p,r){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="异步运镜" tabindex="-1">异步运镜 <a class="header-anchor" href="#异步运镜" aria-label="Permalink to &quot;异步运镜&quot;">​</a></h1><h2 id="功能描述" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述" aria-label="Permalink to &quot;功能描述&quot;">​</a></h2><p>异步运镜（<code>asyncam</code>）用于在不阻塞主线对话流程的情况下，在后台独立运行动画。与同步的 <code>cam</code> 命令不同，<code>asyncam</code> 启动镜头动画后，玩家可以继续点击对话推进剧情，镜头动画在后台独立运行。</p><p>使用场景：</p><ul><li>背景动画/演出与对话同时进行</li><li>玩家可随时点击跳转台词，不受镜头动画影响</li><li>剧情需要镜头瞬间到位时，使用 <code>asyncam stop</code> 强制终止</li></ul><h2 id="语法结构" tabindex="-1">语法结构 <a class="header-anchor" href="#语法结构" aria-label="Permalink to &quot;语法结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asyncam move [目标镜头ID] [过渡类型] [过渡时间]</span></span>
<span class="line"><span>asyncam reset [过渡类型] [过渡时间]</span></span>
<span class="line"><span>asyncam shake [持续时间]</span></span>
<span class="line"><span>asyncam stop</span></span></code></pre></div><h2 id="异步移动-asyncam-move" tabindex="-1">异步移动（asyncam move） <a class="header-anchor" href="#异步移动-asyncam-move" aria-label="Permalink to &quot;异步移动（asyncam move）&quot;">​</a></h2><h3 id="功能描述-1" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述-1" aria-label="Permalink to &quot;功能描述&quot;">​</a></h3><p>将镜头异步移动到指定的目标镜头位置，启动过渡动画后立即返回，不阻塞对话流程。</p><h3 id="参数详解" tabindex="-1">参数详解 <a class="header-anchor" href="#参数详解" aria-label="Permalink to &quot;参数详解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>必需</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>目标镜头ID</td><td>是</td><td><code>cam1</code></td><td>要移动到的镜头资源标识符</td></tr><tr><td>过渡类型</td><td>否</td><td><code>linear</code> / <code>ease_in_out</code> / <code>none</code></td><td>过渡动画类型，不填或填 <code>none</code> 表示无动画</td></tr><tr><td>过渡时间</td><td>否</td><td><code>1.0</code> / <code>2.5</code></td><td>过渡动画的持续时间（秒），默认值为 <code>1.0</code></td></tr></tbody></table><h3 id="过渡类型说明" tabindex="-1">过渡类型说明 <a class="header-anchor" href="#过渡类型说明" aria-label="Permalink to &quot;过渡类型说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>不填</td><td>默认无动画，直接切换</td></tr><tr><td><code>none</code></td><td>显式指定无动画</td></tr><tr><td><code>linear</code></td><td>线性过渡</td></tr><tr><td><code>ease_in_out</code></td><td>缓入缓出过渡</td></tr></tbody></table><h3 id="默认值规则" tabindex="-1">默认值规则 <a class="header-anchor" href="#默认值规则" aria-label="Permalink to &quot;默认值规则&quot;">​</a></h3><ul><li>不写过渡类型 → 无动画，直接切换</li><li>写 <code>none</code> → 无动画</li><li>写其他过渡类型但不写时间 → 默认 <code>1.0</code> 秒</li></ul><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asyncam move cam1</span></span>
<span class="line"><span>asyncam move cam1 none</span></span>
<span class="line"><span>asyncam move cam1 linear</span></span>
<span class="line"><span>asyncam move cam1 linear 1.0</span></span>
<span class="line"><span>asyncam move cam1 ease_in_out 2.5</span></span></code></pre></div><h2 id="异步重置-asyncam-reset" tabindex="-1">异步重置（asyncam reset） <a class="header-anchor" href="#异步重置-asyncam-reset" aria-label="Permalink to &quot;异步重置（asyncam reset）&quot;">​</a></h2><h3 id="功能描述-2" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述-2" aria-label="Permalink to &quot;功能描述&quot;">​</a></h3><p>将镜头异步重置到默认位置（屏幕中心，缩放 1.0），启动过渡动画后立即返回，不阻塞对话流程。</p><h3 id="参数详解-1" tabindex="-1">参数详解 <a class="header-anchor" href="#参数详解-1" aria-label="Permalink to &quot;参数详解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>必需</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>过渡类型</td><td>否</td><td><code>linear</code> / <code>ease_in_out</code> / <code>none</code></td><td>过渡动画类型，不填或填 <code>none</code> 表示无动画</td></tr><tr><td>过渡时间</td><td>否</td><td><code>1.0</code> / <code>2.5</code></td><td>过渡动画的持续时间（秒），默认值为 <code>1.0</code></td></tr></tbody></table><h3 id="默认值规则-1" tabindex="-1">默认值规则 <a class="header-anchor" href="#默认值规则-1" aria-label="Permalink to &quot;默认值规则&quot;">​</a></h3><p>同 <code>asyncam move</code> 的默认值规则。</p><h3 id="示例-1" tabindex="-1">示例 <a class="header-anchor" href="#示例-1" aria-label="Permalink to &quot;示例&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asyncam reset</span></span>
<span class="line"><span>asyncam reset none</span></span>
<span class="line"><span>asyncam reset linear</span></span>
<span class="line"><span>asyncam reset linear 1.0</span></span>
<span class="line"><span>asyncam reset ease_in_out 2.5</span></span></code></pre></div><h2 id="异步晃动-asyncam-shake" tabindex="-1">异步晃动（asyncam shake） <a class="header-anchor" href="#异步晃动-asyncam-shake" aria-label="Permalink to &quot;异步晃动（asyncam shake）&quot;">​</a></h2><h3 id="功能描述-3" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述-3" aria-label="Permalink to &quot;功能描述&quot;">​</a></h3><p>使镜头异步产生随机抖动效果，启动后立即返回，不阻塞对话流程。晃动期间玩家可以正常点击推进对话。</p><h3 id="参数详解-2" tabindex="-1">参数详解 <a class="header-anchor" href="#参数详解-2" aria-label="Permalink to &quot;参数详解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>必需</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td>持续时间</td><td>否</td><td><code>1.0</code> / <code>2.5</code></td><td>晃动持续时间（秒），默认值为 <code>1.0</code></td></tr></tbody></table><h3 id="效果说明" tabindex="-1">效果说明 <a class="header-anchor" href="#效果说明" aria-label="Permalink to &quot;效果说明&quot;">​</a></h3><ul><li>晃动强度随时间逐渐减弱（从强到弱）</li><li>晃动结束后镜头自动恢复到晃动前的位置</li><li>晃动期间会在当前镜头位置周围产生随机偏移</li></ul><h3 id="示例-2" tabindex="-1">示例 <a class="header-anchor" href="#示例-2" aria-label="Permalink to &quot;示例&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asyncam shake</span></span>
<span class="line"><span>asyncam shake 1.0</span></span>
<span class="line"><span>asyncam shake 2.5</span></span></code></pre></div><h2 id="强制停止-asyncam-stop" tabindex="-1">强制停止（asyncam stop） <a class="header-anchor" href="#强制停止-asyncam-stop" aria-label="Permalink to &quot;强制停止（asyncam stop）&quot;">​</a></h2><h3 id="功能描述-4" tabindex="-1">功能描述 <a class="header-anchor" href="#功能描述-4" aria-label="Permalink to &quot;功能描述&quot;">​</a></h3><p>强制终止所有正在运行的异步相机 Tween 动画，相机瞬间直接定格到动画最终目标坐标，放弃剩余过渡动画。</p><p>使用场景：</p><ul><li>玩家点击跳过演出，需要镜头立即到位</li><li>剧情需要镜头瞬间切换，不能再等待当前动画完成</li></ul><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><p>无参数。</p><h3 id="效果说明-1" tabindex="-1">效果说明 <a class="header-anchor" href="#效果说明-1" aria-label="Permalink to &quot;效果说明&quot;">​</a></h3><ul><li>终止所有进行中的异步相机 Tween（move / reset / shake）</li><li>镜头瞬间定格到最终目标位置和缩放</li><li>清除晃动导致的偏移，恢复平稳画面</li><li>对同步 <code>cam</code> 命令的 Tween 无影响</li></ul><h3 id="示例-3" tabindex="-1">示例 <a class="header-anchor" href="#示例-3" aria-label="Permalink to &quot;示例&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asyncam stop</span></span></code></pre></div><h2 id="完整示例" tabindex="-1">完整示例 <a class="header-anchor" href="#完整示例" aria-label="Permalink to &quot;完整示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 异步移动镜头到 cam1，对话继续推进</span></span>
<span class="line"><span>alice &quot;看，那边的风景多美！&quot;</span></span>
<span class="line"><span>asyncam move cam1 linear 3.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 镜头在后台移动中，玩家可以继续点击对话</span></span>
<span class="line"><span>alice &quot;镜头正在慢慢移过去……&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 异步晃动镜头，模拟地震效果</span></span>
<span class="line"><span>asyncam shake 2.0</span></span>
<span class="line"><span>alice &quot;地震了！小心！&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 玩家快速跳过，镜头需要瞬间到位</span></span>
<span class="line"><span>asyncam stop</span></span>
<span class="line"><span>alice &quot;好了，镜头已经到位了。&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 异步重置镜头</span></span>
<span class="line"><span>asyncam reset linear 1.0</span></span>
<span class="line"><span>alice &quot;让我们回到最初的位置。&quot;</span></span></code></pre></div><h2 id="与-cam-命令的区别" tabindex="-1">与 <code>cam</code> 命令的区别 <a class="header-anchor" href="#与-cam-命令的区别" aria-label="Permalink to &quot;与 \`cam\` 命令的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th><code>cam</code>（同步）</th><th><code>asyncam</code>（异步）</th></tr></thead><tbody><tr><td>对话流程</td><td>阻塞，等待动画完成</td><td>不阻塞，立即继续</td></tr><tr><td>后台运行</td><td>否</td><td>是</td></tr><tr><td>玩家可点击跳过</td><td>需等待动画结束</td><td>可随时点击下一句</td></tr><tr><td>强制停止</td><td>不支持</td><td>支持 <code>asyncam stop</code></td></tr><tr><td>适用场景</td><td>需要镜头到位后再继续剧情</td><td>镜头动画与对话并行</td></tr></tbody></table>`,51)])])}const u=e(d,[["render",l]]);export{m as __pageData,u as default};
